import type {Slug} from './ferramentas';
export type Pergunta={pergunta:string;resposta:string};
// revisadoEm: dia da última mudança no texto ou nos exemplos da página (é o <lastmod> dela no sitemap); atualize ao revisar.
// perguntas: aparecem na tela ("Perguntas frequentes") e viram FAQPage; só o que está na tela entra nos dados estruturados.
export type Conteudo={titulo:string;descricaoSEO?:string;introducao:string;passos:string[];exemplos:{titulo:string;conta:string;leitura:string}[];atencao:string;revisadoEm:string;perguntas?:Pergunta[]};
export const conteudos:Record<Slug,Conteudo>={
 'juros-compostos':{revisadoEm:'2026-10-24',titulo:'Calculadora de juros compostos com aportes mensais',introducao:'Nos juros compostos, o rendimento de um mês passa a fazer parte do saldo que rende no mês seguinte. Separar o que você colocou do que veio de juros ajuda a entender o crescimento sem confundir rendimento com esforço de poupança.',passos:['Informe o dinheiro inicial e quanto pretende acrescentar ao fim de cada mês.','Escolha uma taxa mensal ou anual e o prazo. A taxa anual é convertida para uma taxa mensal equivalente.','Use a comparação para mudar o aporte mensal e o controle do gráfico para examinar cada mês.'],exemplos:[{titulo:'Só o valor inicial rendendo',conta:'R$ 1.000 × 1,01 × 1,01 = R$ 1.020,10',leitura:'Com 1% ao mês por dois meses, sem novos depósitos, são R$ 20,10 de juros. No segundo mês, os R$ 10 ganhos no primeiro também rendem.'},{titulo:'Acrescentando R$ 100 por mês',conta:'Mês 1: R$ 1.000 × 1,01 + R$ 100 = R$ 1.110. Mês 2: R$ 1.110 × 1,01 + R$ 100 = R$ 1.221,10.',leitura:'Você colocou R$ 1.200 ao todo. Os outros R$ 21,10 são juros. O aporte do fim do segundo mês só começaria a render no mês seguinte.'}],atencao:'A taxa é uma hipótese constante. A simulação mostra valores nominais e brutos: não desconta imposto, taxas nem inflação e não prevê o retorno de um produto financeiro.'},
 'porcentagem':{revisadoEm:'2026-10-24',titulo:'Calculadora de porcentagem, desconto e aumento',introducao:'Uma porcentagem sempre se refere a uma base. Quinze por cento de R$ 200 são R$ 30; os mesmos 15% sobre R$ 100 são R$ 15. Escolher a base certa é o passo mais importante da conta.',passos:['Escolha entre calcular uma parte, um desconto ou aumento, uma proporção ou uma variação.','Preencha os valores na ordem indicada. Na variação, o primeiro valor é a referência inicial.','Leia o resultado junto da diferença em reais para entender o efeito no orçamento.'],exemplos:[{titulo:'Um desconto na etiqueta',conta:'15% de R$ 200 = R$ 30. Preço final: R$ 200 − R$ 30 = R$ 170.',leitura:'O desconto é calculado sobre o preço original. Você economiza R$ 30 e paga R$ 170.'},{titulo:'O preço subiu e depois caiu',conta:'R$ 100 + 20% = R$ 120. Depois, R$ 120 − 20% = R$ 96.',leitura:'A alta e a queda de 20% não se anulam: a segunda porcentagem usa uma base maior. A diferença final é uma queda de 4% em relação aos R$ 100 iniciais.'}],atencao:'Variação percentual a partir de zero não é definida. Para comparar duas taxas, diferencie porcentagem de pontos percentuais: de 10% para 15% são 5 pontos percentuais, ou aumento relativo de 50%.'},
 'a-vista-ou-parcelado':{revisadoEm:'2026-10-26',titulo:"À vista ou parcelado? Compare o total",descricaoSEO:"Compare o preço à vista com a soma da entrada e das parcelas. Veja a diferença em reais e porcentagem. Calculadora grátis, sem cadastro.",introducao:'O preço de uma parcela pode parecer pequeno, mas a comparação começa pela soma de tudo que será pago. Esta ferramenta coloca entrada e prestações de um lado e o preço à vista do outro.',passos:['Informe o preço total à vista, já com o desconto oferecido.','Preencha a entrada, a quantidade de parcelas e o valor de cada prestação.','Compare o total nominal e a diferença. Depois avalie se a escolha cabe no orçamento.'],exemplos:[
  {
    "titulo": "R$ 900 à vista ou 10 parcelas de R$ 100",
    "conta": "Sem entrada: 10 × R$ 100 = R$ 1.000. Diferença: R$ 1.000 − R$ 900 = R$ 100.",
    "leitura": "À vista, você paga R$ 100 a menos. O desconto é de 10% sobre os R$ 1.000 parcelados. Já o total parcelado é 11,11% maior que os R$ 900 à vista: a base da porcentagem muda. Essa diferença não é uma taxa mensal de juros."
  },
  {
    "titulo": "Compra com entrada: R$ 300 mais 6 parcelas de R$ 150",
    "conta": "R$ 300 + 6 × R$ 150 = R$ 1.200. Com preço à vista de R$ 1.150, a diferença é R$ 50.",
    "leitura": "O total parcelado é 4,35% maior que o preço à vista. Somar apenas as seis parcelas daria R$ 900 e deixaria R$ 300 de fora da comparação. A entrada deve ser incluída uma única vez."
  },
  {
    "titulo": "R$ 1.000 à vista ou 10 parcelas de R$ 100: empate no total",
    "conta": "Sem entrada: 10 × R$ 100 = R$ 1.000. Diferença para o preço à vista: R$ 0.",
    "leitura": "Os totais são iguais. A comparação não considera o rendimento do dinheiro guardado nem as datas dos pagamentos. Confira também como cada opção cabe no seu orçamento."
  }
],atencao:'A ferramenta compara somas nominais. Não calcula CET, valor presente, rendimento do dinheiro guardado, inflação ou custos que não tenham sido incluídos nos preços. Parcelas precisam ter o mesmo valor.'},
 // Texto escrito pelo Claude em 28/10/2026 a pedido do Tiago ("reescreva você"); os números dos exemplos saíram da conta e
 // tests/financiamento.test.mjs confere os mesmos valores.
 'financiamento':{revisadoEm:'2026-10-28',
  titulo:'Simulador de financiamento: SAC ou Price?',
  descricaoSEO:'Simule o financiamento pelo SAC e pela Price: primeira e última parcela, total de juros e o efeito de amortizar antes. Grátis, sem cadastro.',
  introducao:'SAC e Price são dois jeitos de pagar a mesma dívida. No SAC, a parcela começa alta e diminui todo mês, porque você abate sempre a mesma fatia do saldo. Na Price, a parcela é igual do primeiro ao último mês, mas no começo quase tudo vai para os juros. O simulador mostra os dois sistemas lado a lado, mês a mês, para você ver quanto cada um custa antes de assinar.',
  passos:['Informe o valor financiado (o preço do bem menos a entrada), a taxa de juros e o prazo. Se a taxa for ao ano, ela é convertida para a mensal equivalente, sem dividir por 12.','Compare a primeira parcela, a última, o total de juros e o total pago em cada sistema. O gráfico mostra a parcela de cada mês; arraste o controle para ver um mês específico.','Pretende usar o 13º, um bônus ou uma reserva para pagar uma parte antes? Informe o valor e o mês da amortização extra e escolha se quer encurtar o prazo ou baixar a parcela.'],
  exemplos:[
   {titulo:'R$ 300 mil em 30 anos a 1% ao mês: qual sistema custa menos?',conta:'Price: 360 parcelas de R$ 3.085,84; juros de R$ 810.901,60. SAC: a parcela começa em R$ 3.833,33 e termina em R$ 841,67; juros de R$ 541.500,00.',leitura:'A Price começa R$ 747,50 mais barata e fica igual até o fim. O SAC pede mais nos primeiros anos, mas a parcela cai a cada mês e os juros somam R$ 269.401,60 a menos. A diferença está entre o que cabe no orçamento hoje e o que se paga de juros no total.'},
   {titulo:'R$ 200 mil em 20 anos a 10,5% ao ano: por que a taxa não é dividida por 12?',conta:'Taxa mensal equivalente: 0,8355% (e não 0,875%). Price: 240 parcelas de R$ 1.933,51; juros de R$ 264.043,50. SAC: de R$ 2.504,36 a R$ 840,30; juros de R$ 201.359,25.',leitura:'Juros são compostos: 0,8355% ao mês, durante 12 meses, dá exatamente 10,5% ao ano. Dividir 10,5% por 12 daria uma taxa maior e uma parcela errada. Neste caso, o SAC pede R$ 570,85 a mais no primeiro mês e economiza R$ 62.684,24 em juros.'},
   {titulo:'O que muda ao amortizar R$ 50 mil no 12º mês?',conta:'Price de R$ 300 mil a 1% ao mês. Pagando R$ 50 mil a mais no 12º mês e mantendo a parcela de R$ 3.085,84, o contrato termina no mês 178, com juros de R$ 296.604,08.',leitura:'São 182 parcelas a menos e R$ 514.297,53 a menos em juros. O pagamento extra abate o saldo devedor, e os juros de todos os meses seguintes são calculados sobre um saldo menor. Se você preferir baixar a parcela e manter o prazo, a economia em juros é menor, mas a folga no orçamento vem já no mês seguinte.'}
  ],
  perguntas:[
   {pergunta:'O que é o SAC?',resposta:'SAC é o Sistema de Amortização Constante. Todo mês você abate a mesma fatia do valor financiado (o valor dividido pelo número de meses) e paga os juros sobre o saldo que ainda falta. Como o saldo diminui, os juros caem e a parcela também.'},
   {pergunta:'O que é a tabela Price?',resposta:'Na tabela Price (Sistema Francês de Amortização), a parcela é fixa do começo ao fim. No início, a maior parte dela paga juros e pouco abate a dívida; com o tempo, a proporção se inverte. É o sistema mais comum em empréstimos pessoais e no crédito de veículos.'},
   {pergunta:'SAC ou Price: qual é mais barato?',resposta:'Com a mesma taxa e o mesmo prazo, o SAC paga menos juros no total, porque abate a dívida mais rápido. Em troca, as primeiras parcelas são maiores. A Price tem a parcela inicial menor e igual até o fim, mas custa mais em juros. O simulador mostra a diferença em reais para os seus números.'},
   {pergunta:'Por que a parcela do banco é maior do que a do simulador?',resposta:'O simulador calcula só amortização e juros. No financiamento imobiliário, a parcela do contrato inclui os seguros obrigatórios (MIP, por morte e invalidez, e DFI, por danos ao imóvel), a taxa de administração e, em muitos contratos, a correção do saldo pela TR ou pelo IPCA. Para comparar propostas, use o Custo Efetivo Total (CET), que o banco é obrigado a informar.'},
   {pergunta:'Amortizar antes reduz o prazo ou a parcela?',resposta:'Você escolhe. Ao reduzir o prazo, a parcela continua a mesma e o contrato acaba antes: é a opção que mais economiza juros. Ao reduzir a parcela, o prazo continua e você passa a pagar menos por mês. Nos dois casos, o pagamento extra abate o saldo devedor, e os juros seguintes são calculados sobre um saldo menor.'}
  ],
  atencao:'A simulação usa uma taxa constante e considera só amortização e juros: não entram seguros, taxa de administração, IOF nem a correção do saldo pela TR ou pelo IPCA, então a parcela do contrato costuma ser maior. Compare propostas pelo Custo Efetivo Total (CET). Não é previsão nem recomendação, nem uma oferta de crédito.'
 },
 'quanto-rende':{revisadoEm:'2026-10-28',
  // Texto escrito pelo Claude em 28/10/2026 a pedido do Tiago ("reescreva você"); os números dos exemplos saem de lib/calculos/quanto-rende.ts e o teste confere.
  titulo:'Quanto rende: poupança, CDB, LCI ou Tesouro Selic?',
  descricaoSEO:'Compare quanto rende o mesmo dinheiro na poupança, no CDB, na LCI ou LCA e no Tesouro Selic, já com IOF, imposto de renda e custódia. Grátis, sem cadastro.',
  introducao:'A taxa anunciada não é o que entra na sua conta. O CDB e o Tesouro Selic pagam imposto de renda, que cai conforme o prazo; nos primeiros 30 dias há IOF; no Tesouro, a B3 cobra custódia sobre o que passa de R$ 10 mil. A LCI e a LCA são isentas, e a poupança também, mas ela só rende no aniversário. A calculadora põe as quatro opções no mesmo prazo e mostra o líquido de cada uma, para a comparação ser justa.',
  passos:['Informe quanto vai aplicar e por quanto tempo, em dias, meses ou anos. O prazo define a alíquota do imposto de renda e se há IOF.','Digite o CDI ao ano e quanto do CDI cada título paga. Um CDB a 100% do CDI e uma LCI a 90% são ofertas comuns; a do seu banco ou corretora pode ser outra.','Compare o valor líquido de cada opção. O ponto de empate diz quanto do CDI o CDB precisa pagar para valer tanto quanto a LCI, que não paga imposto.'],
  exemplos:[
   {titulo:'R$ 10 mil por 2 anos, com o CDI a 14,65%: qual rende mais?',conta:'CDB a 100% do CDI: R$ 13.144,62 brutos, menos R$ 471,69 de imposto (15%) = R$ 12.672,93. LCI a 90% do CDI: R$ 12.790,17, sem imposto. Tesouro Selic: R$ 12.666,64 (imposto de R$ 471,69 e custódia de R$ 6,29). Poupança a 0,5% ao mês: R$ 11.271,60.',leitura:'A LCI a 90% do CDI rende mais do que o CDB a 100%, porque não paga imposto: um CDB só empata pagando 103,82% do CDI. A poupança fica R$ 1.518,57 atrás da LCI em dois anos. Entre o CDB e o Tesouro Selic, a diferença é só a custódia da B3 sobre o que passa de R$ 10 mil.'},
   {titulo:'R$ 50 mil por 1 ano: CDB a 110% do CDI ou LCI a 85%?',conta:'CDB a 110% do CDI: R$ 58.113,86 brutos, menos R$ 1.419,92 de imposto (17,5%) = R$ 56.693,93. LCI a 85%: R$ 56.161,67. Tesouro Selic: R$ 55.955,80. Poupança: R$ 53.083,89.',leitura:'Aqui o CDB ganha mesmo pagando imposto: 110% do CDI compensa a alíquota de 17,5%. O empate com essa LCI está em 101,83% do CDI; acima disso, o CDB rende mais. Em um ano, a poupança rende R$ 3.610,04 a menos do que o CDB.'},
   {titulo:'R$ 5 mil por 15 dias: por que o CDB rende tão pouco?',conta:'CDB a 100% do CDI: R$ 28,17 de rendimento bruto; IOF de 50% (R$ 14,09) e imposto de 22,5% sobre o que sobra (R$ 3,17); líquido de R$ 5.010,92. LCI a 90%: R$ 5.025,35. Poupança: R$ 5.000,00.',leitura:'Em prazos curtos o IOF pesa: ele come metade do rendimento no 15º dia e só zera no 30º. A poupança não rendeu nada, porque o dinheiro saiu antes do aniversário mensal. E a LCI, apesar do número, raramente serve para 15 dias: ela tem prazo mínimo de resgate, fixado pelo Conselho Monetário Nacional.'}
  ],
  perguntas:[
   {pergunta:'Qual é a alíquota do imposto de renda na renda fixa?',resposta:'A tabela é regressiva: 22,5% para aplicações de até 180 dias, 20% de 181 a 360 dias, 17,5% de 361 a 720 dias e 15% acima de 720 dias. O imposto incide só sobre o rendimento e é descontado na fonte, no resgate ou no vencimento. Vale para CDB, Tesouro Direto e a maioria dos fundos de renda fixa.'},
   {pergunta:'O que é o IOF nos primeiros 30 dias?',resposta:'É um imposto sobre o rendimento de quem resgata antes de 30 dias. Ele começa em 96% do rendimento no 1º dia, cai um pouco a cada dia e chega a 3% no 29º; a partir do 30º dia é zero. O imposto de renda é calculado sobre o que sobra depois do IOF.'},
   {pergunta:'LCI e LCA são isentas de imposto?',resposta:'Para pessoa física, o rendimento da LCI e da LCA é isento de imposto de renda. Em troca, elas têm prazo mínimo de resgate, fixado pelo Conselho Monetário Nacional, e a oferta costuma pagar um percentual menor do CDI. Confira a regra em vigor na data da aplicação: a isenção já foi discutida no Congresso.'},
   {pergunta:'Por que a poupança rende menos?',resposta:'Pela regra em vigor desde 2012, a poupança paga 0,5% ao mês mais a TR quando a Selic está acima de 8,5% ao ano (cerca de 6,2% ao ano, sem a TR), enquanto CDB, LCI e Tesouro Selic acompanham o CDI, que anda perto da Selic. Além disso, ela só rende no aniversário mensal: quem saca antes perde o rendimento do mês. É isenta de imposto, mas isso não compensa a diferença quando a Selic está alta.'},
   {pergunta:'Tesouro Selic ou CDB a 100% do CDI?',resposta:'Os dois pagam o mesmo imposto e rendem perto da mesma taxa. O Tesouro Selic tem a custódia da B3 (0,2% ao ano sobre o que passa de R$ 10 mil) e o risco do governo federal; o CDB tem o risco do banco emissor, com a garantia do FGC até o limite por CPF e instituição. A calculadora mostra só o rendimento, não o risco.'},
   {pergunta:'O que é o ponto de empate entre CDB e LCI?',resposta:'É o percentual do CDI que o CDB precisa pagar para o seu rendimento líquido, depois do imposto, igualar o da LCI, que é isenta. Ele depende do prazo, porque a alíquota muda: com o CDI a 14,65%, uma LCI a 90% do CDI equivale a um CDB a 103,82% em 2 anos (imposto de 15%) e a 115,97% em 30 dias (imposto de 22,5%).'}
  ],
  atencao:'Simulação com a taxa que você digitou; não é previsão nem recomendação. O CDI de amanhã não é o de hoje, e os rendimentos pós-fixados mudam com ele. Ficam de fora a TR da poupança, o calendário de feriados (dias úteis pela proporção 252/365), a carência de cada título, o risco do emissor, o FGC e a marcação a mercado. Confira a alíquota e a isenção em vigor na data da aplicação.'
 },
 'quanto-guardar-por-mes':{revisadoEm:'2026-10-26',
  titulo:'Quanto guardar por mês? Calculadora de metas',
  descricaoSEO:'Calcule quanto guardar por mês para atingir sua meta. Informe quanto quer juntar, o que já tem e o prazo. Simule com ou sem juros.',
  introducao:'Uma meta fica mais concreta quando vira um valor mensal. A calculadora parte do quanto você já tem e estima o aporte necessário para chegar ao objetivo no prazo escolhido.',
  passos:['Defina o valor da meta e quanto já está separado para ela.','Informe o prazo e uma taxa mensal hipotética. Use zero para planejar sem depender de rendimento.','Compare o aporte necessário com seu orçamento e teste um prazo diferente quando precisar.'],
  exemplos:[
   {titulo:'Quanto guardar por mês para juntar R$ 10 mil em dois anos?',conta:'Se você já tem R$ 1.000, faltam R$ 9.000 para chegar à meta. Sem considerar juros, dividindo esse valor por 24 meses, a conta fica em R$ 375 por mês.',leitura:'Na calculadora: meta de R$ 10.000, valor inicial de R$ 1.000, prazo de 24 meses e rendimento mensal de 0%.'},
   {titulo:'Quanto guardar para juntar R$ 6 mil em um ano?',conta:'Começando do zero e sem considerar juros, são R$ 500 por mês durante 12 meses. Se o prazo passar para dois anos, o valor cai para R$ 250 por mês.',leitura:'Na calculadora: meta de R$ 6.000, valor inicial de R$ 0 e rendimento mensal de 0%. Compare os prazos de 12 e 24 meses.'},
   {titulo:'Guardando R$ 300 por mês, em quanto tempo junto R$ 6 mil?',conta:'Sem dinheiro inicial e sem considerar juros, a conta é R$ 6.000 ÷ R$ 300 = 20 meses. Isso corresponde a um ano e oito meses.',leitura:'Para conferir na calculadora: informe meta de R$ 6.000, valor inicial de R$ 0, prazo de 20 meses e rendimento mensal de 0%. O resultado será R$ 300 por mês.'}
  ],
  atencao:'A meta fica em reais nominais: se o preço do objetivo subir, será necessário revisá-la. Aportes acontecem no fim de cada mês e o rendimento informado é uma hipótese, sem impostos e custos.'
 },
 'emprestimo':{revisadoEm:'2026-10-29',
  // Texto escrito pelo Claude em 29/10/2026 (rascunho, nível 1: publicado só com o "pode"); os números dos exemplos saem de lib/calculos/emprestimo.ts e o teste confere.
  titulo:'Empréstimo: parcela, juros total e CET, com IOF e tarifa',
  descricaoSEO:'Simule um empréstimo pessoal: parcela pela tabela Price, juros no total e o CET (Custo Efetivo Total) com IOF e tarifa, e compare o mesmo empréstimo em outros prazos. Grátis, sem cadastro.',
  introducao:'A taxa de juros que o banco anuncia não é tudo o que você paga. No empréstimo pessoal entram também o IOF, imposto federal sobre o crédito, e, em alguns contratos, uma tarifa de cadastro. O número que junta tudo isso é o CET, o Custo Efetivo Total, que toda instituição é obrigada a informar antes da assinatura. Esta calculadora mostra a parcela, quanto você paga de juros no total e o CET ao mês e ao ano, e põe o mesmo empréstimo lado a lado em outros prazos, para você ver o que uma parcela menor custa no fim.',
  passos:['Informe quanto quer receber, a taxa de juros (ao mês ou ao ano, como está na proposta) e o número de parcelas.','Se o contrato tem tarifa de cadastro, digite o valor; deixe o IOF ligado, a menos que a operação seja isenta. Escolha se esses custos entram na dívida (você recebe o valor inteiro e paga parcelas maiores) ou saem do valor liberado (a dívida é a que você digitou e cai menos na conta).','Leia o CET ao ano no resultado e compare com o CET da proposta do banco. Na tabela do mesmo empréstimo em outros prazos, veja quanto a parcela cai e quanto o custo total sobe quando o prazo cresce.'],
  exemplos:[
   {titulo:'R$ 5.000 em 12 parcelas a 3% ao mês, com IOF',conta:'O IOF de R$ 105,45 entra na dívida: R$ 5.105,45 financiados e parcela de R$ 512,90. Em 12 meses, R$ 6.154,85 pagos, R$ 1.049,40 de juros e R$ 1.154,85 de custo total.',leitura:'A taxa é 3% ao mês (42,58% ao ano), mas o CET é 3,35% ao mês, 48,52% ao ano: o IOF, que não vira dinheiro na sua mão, aparece aí. Para comparar propostas, olhe o CET, não a taxa.'},
   {titulo:'R$ 20.000 em 36 parcelas a 1,8% ao mês, com tarifa de R$ 150',conta:'Tarifa e IOF (R$ 626,92) entram na dívida: R$ 20.776,92 financiados, parcela de R$ 789,19. No fim, R$ 28.410,74 pagos, R$ 7.633,81 de juros e R$ 8.410,74 de custo total.',leitura:'Em três anos os juros passam de um terço do que você recebeu. O CET é 2,04% ao mês, 27,36% ao ano, contra 23,87% ao ano da taxa; o IOF pesa menos aqui porque a parte diária para de crescer depois de 365 dias.'},
   {titulo:'R$ 10.000 em 24 parcelas a 2,5% ao mês, sem IOF nem tarifa',conta:'Parcela de R$ 559,13; R$ 13.419,08 pagos e R$ 3.419,08 de juros, que é também o custo total.',leitura:'Sem custo além dos juros, o CET é a própria taxa: 2,5% ao mês, 34,49% ao ano. É a conta de uma proposta sem IOF e sem tarifa; se a sua tem IOF, ligue o campo e veja a diferença.'}
  ],
  perguntas:[
   {pergunta:'O que é o CET e por que ele é maior que a taxa de juros?',resposta:'CET é o Custo Efetivo Total: a taxa que resume tudo o que você paga pelo crédito, não só os juros, mas também o IOF, tarifas e seguros cobrados na operação. Pela Resolução CMN 4.881/2020, a instituição é obrigada a informar o CET antes da contratação. Ele fica acima da taxa de juros sempre que há algum custo além dos juros, porque esse custo sai do seu bolso sem virar dinheiro na sua mão. É o CET, e não a taxa, que se compara entre propostas.'},
   {pergunta:'Por que a parcela aqui é diferente da do banco?',resposta:'Três motivos comuns: o banco conta os dias do calendário no IOF e nos juros, e a calculadora usa meses de 30 dias; a primeira parcela pode vencer em mais ou menos de 30 dias, o que muda os juros do primeiro mês; e seguros ou outras tarifas podem estar embutidos. Diferenças de centavos são normais. Uma diferença grande merece pergunta ao banco: o contrato tem de mostrar o CET e cada custo.'},
   {pergunta:'Como o IOF é cobrado no empréstimo?',resposta:'O IOF do crédito à pessoa física tem duas partes (Decreto 6.306/2007, art. 7º): 0,38% sobre o valor da operação e 0,0082% por dia sobre o principal, limitado a 365 dias. Na prática, cada parcela paga 0,38% mais 0,0082% por dia entre a liberação e o vencimento dela; o que vence depois de um ano paga o máximo, 0,38% + 2,993% = 3,373%. Normalmente o IOF é financiado junto com a dívida, por isso o valor financiado fica maior que o liberado. As mudanças de 2025 no IOF do crédito mexeram nas operações de empresas; as alíquotas da pessoa física usadas aqui foram conferidas até 31/12/2026.'},
   {pergunta:'Tarifa financiada ou descontada: qual é a diferença?',resposta:'Financiada, a tarifa (e o IOF) entra na dívida: você recebe o valor inteiro e paga parcelas um pouco maiores. Descontada, a dívida é o valor pedido, mas cai menos na conta. O CET fica um pouco maior na forma descontada, porque você paga as mesmas parcelas tendo recebido menos. A tarifa de cadastro é regulada pelo Banco Central (Resolução CMN 3.919/2010): só pode ser cobrada no início do relacionamento com a instituição, uma vez, e tem de estar no contrato.'},
   {pergunta:'Taxa ao mês ou ao ano: como converter?',resposta:'Pela equivalência composta: 3% ao mês equivalem a (1,03)^12 − 1 = 42,58% ao ano, e não a 36%. A calculadora faz a conversão quando você troca o período no seletor. Propostas costumam mostrar as duas taxas; a comparação entre bancos deve usar o mesmo período e, de preferência, o CET.'},
   {pergunta:'Posso quitar antes e pagar menos juros?',resposta:'Sim. Na quitação antecipada, total ou parcial, você tem direito ao abatimento proporcional dos juros (Código de Defesa do Consumidor, art. 52, § 2º), e a instituição não pode cobrar tarifa por isso (Resolução CMN 3.516/2007). Também é possível levar a dívida para outro banco com CET menor pela portabilidade de crédito (Resolução CMN 4.292/2013), sem tarifa de portabilidade. Esta calculadora não simula a antecipação: use a calculadora de financiamento para ver o efeito de amortizar antes.'}
  ],
  atencao:'Simulação com os valores que você digitou; não é previsão nem recomendação, nem uma oferta de crédito. Alíquotas do IOF da pessoa física conferidas até 31/12/2026 (Decreto 6.306/2007); os meses são contados com 30 dias, então o IOF do banco, que conta os dias do calendário, pode diferir em centavos. Ficam de fora seguros, tarifa embutida na taxa, multa e juros de atraso, as regras do crédito consignado e a antecipação de parcelas. O CET da sua proposta é o que vale: ele está no contrato por obrigação do Banco Central.'},
 'salario-liquido':{revisadoEm:'2026-10-29',
  // Texto escrito pelo Claude em 29/10/2026 ("reescreva você", 28/10); os números dos exemplos saem de lib/calculos/salario-liquido.ts e o teste confere.
  titulo:'Salário líquido 2026: quanto cai na conta depois do INSS e do imposto',
  descricaoSEO:'Calcule o salário líquido de 2026: INSS por faixa, imposto de renda com dependentes ou desconto simplificado e a redução da Lei 15.270 para quem ganha até R$ 7.350. Grátis, sem cadastro.',
  introducao:'O salário combinado é o bruto; o que cai na conta é o líquido. No meio ficam o INSS, que desconta uma alíquota por faixa (quem ganha R$ 3 mil não paga 12% sobre tudo, só sobre a fatia acima de R$ 2.902,84), e o imposto de renda, calculado sobre o que sobra depois das deduções. Desde janeiro de 2026 há ainda a redução da Lei 15.270: quem ganha até R$ 5 mil fica sem imposto, e quem ganha até R$ 7.350 paga menos. A calculadora usa as tabelas de 2026 e mostra cada desconto separado, como deveria aparecer no holerite.',
  passos:['Informe o salário bruto do mês: o valor antes de qualquer desconto, como está no contrato ou no topo do holerite.','Diga quantos dependentes você declara no imposto de renda. Cada um deduz R$ 189,59 da base; a calculadora compara com o desconto simplificado de R$ 607,20 e usa o que for melhor para você, como a empresa deve fazer.','Se quiser, inclua outros descontos da folha, como vale-transporte e plano de saúde. Eles saem do líquido, mas não mudam o imposto.'],
  exemplos:[
   {titulo:'R$ 3.000 sem dependentes: quanto sobra?',conta:'INSS: 7,5% sobre R$ 1.621,00 + 9% sobre R$ 1.281,84 + 12% sobre R$ 97,16 = R$ 248,60. Imposto de renda: a base pelo desconto simplificado é R$ 3.000 − R$ 607,20 = R$ 2.392,80, abaixo da faixa isenta (R$ 2.428,80); zero. Líquido: R$ 2.751,40.',leitura:'O INSS leva 8,3% do bruto, e não 12%, porque cada alíquota só vale na sua faixa. O desconto simplificado foi melhor do que deduzir o INSS (R$ 607,20 contra R$ 248,60), e com ele a base já fica na faixa isenta: aqui a redução da Lei 15.270 nem chega a ser usada.'},
   {titulo:'R$ 6.000 com 1 dependente: a redução ainda ajuda?',conta:'INSS: R$ 641,51 (o salário chega à faixa de 14%). Deduções legais: R$ 641,51 de INSS + R$ 189,59 do dependente, base de R$ 5.168,90, menor que a do desconto simplificado (R$ 5.392,80). Imposto pela tabela: 27,5% × R$ 5.168,90 − R$ 908,73 = R$ 512,72. Redução da Lei 15.270: R$ 978,62 − 0,133145 × R$ 6.000 = R$ 179,75. Imposto de renda: R$ 332,97. Líquido: R$ 5.025,52.',leitura:'Entre R$ 5.000,01 e R$ 7.350 de salário bruto a redução vai encolhendo: em R$ 6 mil ela ainda tira R$ 179,75 do imposto. O dependente valeu: sem ele a base seria R$ 5.358,49 e o imposto, R$ 385,10, ou R$ 52,13 a mais por mês.'},
   {titulo:'R$ 10.000 com 2 dependentes: INSS no teto',conta:'INSS: R$ 988,09, o máximo de 2026 (teto de R$ 8.475,55). Deduções legais: R$ 988,09 + 2 × R$ 189,59 = R$ 1.367,27; base de R$ 8.632,73. Imposto: 27,5% × R$ 8.632,73 − R$ 908,73 = R$ 1.465,27, sem redução (salário acima de R$ 7.350). Líquido: R$ 7.546,64.',leitura:'Acima do teto o INSS para de crescer, por isso a alíquota efetiva dele cai (9,9% aqui). O imposto de renda tem alíquota marginal de 27,5%, mas fica em 14,7% do bruto, porque a parcela a deduzir e as deduções abatem a conta.'}
  ],
  perguntas:[
   {pergunta:'Por que o INSS não é 12% sobre todo o salário?',resposta:'Desde 2020 a contribuição do empregado é progressiva, como o imposto de renda: 7,5% até R$ 1.621,00, 9% da parte entre R$ 1.621,01 e R$ 2.902,84, 12% da parte entre R$ 2.902,85 e R$ 4.354,27 e 14% da parte entre R$ 4.354,28 e o teto de R$ 8.475,55 (valores de 2026). Cada alíquota só vale na sua faixa, e o que passa do teto não contribui. O desconto máximo em 2026 é R$ 988,09.'},
   {pergunta:'O que é o desconto simplificado do imposto de renda?',resposta:'É um valor fixo, de R$ 607,20 por mês em 2026, que substitui todas as deduções legais (INSS, dependentes, pensão alimentícia, previdência). A fonte pagadora deve aplicar o que for melhor para o empregado: para salários menores, o simplificado costuma ganhar; para quem tem INSS alto ou vários dependentes, as deduções legais ganham. A calculadora compara os dois e diz qual usou.'},
   {pergunta:'Quem ganha até R$ 5 mil não paga mais imposto de renda?',resposta:'Desde janeiro de 2026, pela Lei 15.270/2025, quem tem rendimento tributável mensal de até R$ 5.000 recebe uma redução de até R$ 312,89, que zera o imposto calculado pela tabela. Entre R$ 5.000,01 e R$ 7.350 a redução diminui aos poucos (R$ 978,62 menos 0,133145 vezes o rendimento) e acima de R$ 7.350 nada muda. A redução vale também no 13º. A tabela progressiva em si continuou a mesma, com isenção até R$ 2.428,80 de base de cálculo.'},
   {pergunta:'Quanto cada dependente abate?',resposta:'R$ 189,59 por mês da base de cálculo, dentro das deduções legais. Podem ser dependentes, entre outros, filhos até 21 anos (ou até 24 se estiverem na faculdade) e o cônjuge, nas regras da Receita Federal. O abatimento só faz diferença quando as deduções legais são melhores que o desconto simplificado, e o dependente só pode ser declarado por uma pessoa.'},
   {pergunta:'Vale-transporte e plano de saúde mudam o imposto?',resposta:'Não no cálculo mensal. O vale-transporte é descontado em até 6% do salário básico e o plano de saúde é um desconto da folha; nenhum dos dois reduz a base do imposto retido na fonte. Gastos com saúde podem ser deduzidos na declaração anual. Por isso a calculadora põe esses valores em "outros descontos": saem do líquido, sem mexer no imposto.'},
   {pergunta:'As tabelas mudam todo ano?',resposta:'O INSS muda em janeiro, por portaria, junto com o salário mínimo e o teto; em 2026 a Portaria Interministerial MPS/MF nº 13 trouxe as faixas usadas aqui. A tabela do imposto de renda só muda por lei: a atual é da Lei 15.191/2025, e a redução veio pela Lei 15.270/2025. Esta calculadora usa as tabelas de 2026, conferidas até 31/12/2026, e avisa na tela quando o prazo estiver perto.'}
  ],
  atencao:'Simulação com os valores que você digitou; não é previsão nem recomendação. As tabelas são as de 2026 (INSS pela Portaria Interministerial MPS/MF nº 13/2026; imposto de renda pelas Leis 15.191/2025 e 15.270/2025) e valem para empregado com um só emprego. Ficam de fora: 13º, férias, horas extras e adicionais, pensão alimentícia, previdência privada, salário-família, outros vínculos e os regimes próprios de servidor. O holerite pode diferir por centavos pelo jeito de arredondar de cada folha.'
 },
 'decimo-terceiro':{revisadoEm:'2026-10-29',
  // Rascunho do Claude em 29/10/2026 (nível 1: o texto público espera o "pode" do Tiago); os números dos exemplos saem de lib/calculos/decimo-terceiro.ts e o teste confere.
  titulo:'13º salário 2026: 1ª e 2ª parcela, proporcional e com os descontos',
  descricaoSEO:'Calcule o 13º salário de 2026: integral ou proporcional pela regra dos 15 dias, a 1ª parcela até 30/11 sem desconto e a 2ª até 20/12 com INSS e imposto de renda. Grátis, sem cadastro.',
  introducao:'O 13º salário é um salário a mais por ano: 1/12 da remuneração de dezembro para cada mês trabalhado, e um mês com 15 dias ou mais de trabalho conta inteiro. Ele chega em duas vezes. A 1ª parcela, até 30 de novembro, é a metade do valor e vem sem nenhum desconto. A 2ª parcela, até 20 de dezembro, é o que falta menos o INSS e o imposto de renda, os dois calculados sobre o 13º inteiro e separados do salário do mês; por isso a 2ª parcela é sempre menor que a 1ª. A calculadora usa as tabelas de 2026 (as mesmas do salário líquido, com a redução da Lei 15.270 aplicada ao 13º) e mostra mês a mês quais contam para quem entrou durante o ano.',
  passos:['Informe o salário bruto mensal, o de dezembro, antes dos descontos. Se você recebe horas extras, comissões ou adicionais, coloque a média mensal do ano no segundo campo: ela entra na base do 13º.','Diga quantos dependentes você declara no imposto de renda e a data de admissão. Quem entrou antes de 2026 recebe o 13º integral; quem entrou durante o ano recebe um avo por mês com 15 dias ou mais de trabalho, e a tabela "Os meses que contam" mostra cada um.','Se a empresa já pagou a 1ª parcela (nas férias ou em novembro), informe o valor exato recebido: a 2ª parcela é a diferença. Em branco, a calculadora usa a metade do 13º.'],
  exemplos:[
   {titulo:'R$ 3.000 o ano inteiro: quanto vem em novembro e em dezembro?',conta:'13º integral: R$ 3.000,00. 1ª parcela: R$ 1.500,00, sem desconto. INSS sobre os R$ 3.000: 7,5% sobre R$ 1.621,00 + 9% sobre R$ 1.281,84 + 12% sobre R$ 97,16 = R$ 248,60. Imposto de renda: a base pelo desconto simplificado é R$ 3.000 − R$ 607,20 = R$ 2.392,80, abaixo da faixa isenta; zero. 2ª parcela: R$ 3.000,00 − R$ 1.500,00 − R$ 248,60 = R$ 1.251,40. Líquido total: R$ 2.751,40.',leitura:'A 2ª parcela é menor que a 1ª porque carrega sozinha o INSS do 13º inteiro. O imposto não aparece aqui pelo mesmo motivo do salário mensal de R$ 3 mil: com o desconto simplificado, a base fica na faixa isenta.'},
   {titulo:'R$ 6.000 com 1 dependente: a redução de 2026 vale no 13º?',conta:'13º integral: R$ 6.000,00; 1ª parcela: R$ 3.000,00. INSS sobre os R$ 6.000: R$ 641,51. Deduções legais: R$ 641,51 de INSS + R$ 189,59 do dependente, base de R$ 5.168,90 (menor que a do desconto simplificado, R$ 5.392,80). Imposto pela tabela: 27,5% × R$ 5.168,90 − R$ 908,73 = R$ 512,72. Redução da Lei 15.270: R$ 978,62 − 0,133145 × R$ 6.000 = R$ 179,75. Imposto de renda: R$ 332,97. 2ª parcela: R$ 6.000,00 − R$ 3.000,00 − R$ 641,51 − R$ 332,97 = R$ 2.025,52. Líquido total: R$ 5.025,52.',leitura:'Vale: a redução é calculada de novo sobre o 13º, separada do salário do mês, e aqui tira R$ 179,75 do imposto. O 13º tem os mesmos descontos do salário de dezembro, só que concentrados na 2ª parcela: de R$ 6 mil, R$ 2.025,52 chegam em dezembro.'},
   {titulo:'R$ 3.000 para quem entrou em 10 de abril de 2026: 13º proporcional',conta:'Abril teve 21 dias trabalhados (15 ou mais: conta); de maio a dezembro, 8 meses inteiros. Total: 9 avos. 13º: R$ 3.000 × 9/12 = R$ 2.250,00. 1ª parcela: R$ 1.125,00. INSS sobre os R$ 2.250: 7,5% sobre R$ 1.621,00 + 9% sobre R$ 629,00 = R$ 178,19. Imposto de renda: zero. 2ª parcela: R$ 2.250,00 − R$ 1.125,00 − R$ 178,19 = R$ 946,81.',leitura:'Se a admissão fosse em 17 de abril, abril teria 14 dias e não contaria: 8 avos, R$ 2.000,00 de 13º. Os descontos saem do valor proporcional, não do salário cheio, por isso o INSS aqui é menor que o do salário mensal.'}
  ],
  perguntas:[
   {pergunta:'Quando a empresa tem de pagar o 13º?',resposta:'A 1ª parcela entre fevereiro e 30 de novembro (Lei 4.749/1965); muitas empresas pagam em novembro, e o empregado pode pedir o adiantamento nas férias, por escrito, em janeiro. A 2ª parcela até 20 de dezembro. Se o dia 20 cai em fim de semana ou feriado, o pagamento é antecipado.'},
   {pergunta:'Por que a 2ª parcela é menor que a 1ª?',resposta:'A 1ª parcela é a metade do 13º bruto, sem nenhum desconto. O INSS e o imposto de renda são calculados sobre o 13º inteiro e descontados todos na 2ª parcela. É por isso que o valor de dezembro surpreende: ele carrega os descontos das duas metades.'},
   {pergunta:'Como funciona a regra dos 15 dias?',resposta:'Cada mês do ano vale 1/12 do 13º (um avo). Um mês com 15 dias ou mais de trabalho conta inteiro; com 14 ou menos, não conta (Lei 4.090/1962, art. 1º, § 2º). Quem foi admitido em 16 de abril tem abril (15 dias) e os 8 meses seguintes: 9 avos. Quem entrou em 17 de abril tem 8. Faltas injustificadas e afastamentos longos também podem tirar avos, e a calculadora não trata disso.'},
   {pergunta:'O imposto de renda do 13º soma com o do salário?',resposta:'Não. O 13º tem tributação exclusiva na fonte: o imposto é calculado só sobre ele, com a tabela mensal, as deduções (INSS do 13º e dependentes, ou o desconto simplificado) e a redução da Lei 15.270/2025, e é definitivo: não entra na declaração anual nem no ajuste. Por isso quem ganha R$ 5 mil e fica sem imposto no salário também fica sem imposto no 13º.'},
   {pergunta:'Horas extras, comissões e adicionais entram no 13º?',resposta:'Sim. A base do 13º é a remuneração de dezembro, com a média das parcelas variáveis recebidas no ano (horas extras, comissões, adicional noturno, insalubridade, periculosidade). Informe a média mensal no campo próprio. Vale-transporte, vale-refeição e participação nos lucros não entram.'},
   {pergunta:'E quem foi demitido ou pediu demissão durante o ano?',resposta:'Recebe o 13º proporcional aos meses trabalhados na rescisão, exceto na demissão por justa causa. Essa conta faz parte da rescisão, com outras verbas (saldo de salário, aviso prévio, férias), e não está nesta calculadora: aqui o 13º é de quem está empregado em dezembro.'}
  ],
  atencao:'Simulação com os valores que você digitou; não é previsão nem recomendação. As tabelas são as de 2026 (INSS pela Portaria Interministerial MPS/MF nº 13/2026; imposto de renda pelas Leis 15.191/2025 e 15.270/2025) e valem para empregado CLT com um só emprego. Ficam de fora: faltas e afastamentos que tiram avos, pensão alimentícia, previdência privada, o 13º pago na rescisão, mais de um vínculo e os regimes próprios de servidor. A empresa pode escolher como aplica as deduções do imposto (legais ou simplificado), e cada folha arredonda do seu jeito: confira o holerite.'},
 'rescisao':{revisadoEm:'2026-10-29',
  // Rascunho do Claude em 29/10/2026 (nível 1: o texto público espera o "pode" do Tiago); os números dos exemplos saem de lib/calculos/rescisao.ts e o teste confere.
  titulo:'Rescisão 2026: saldo de salário, aviso prévio, 13º, férias e multa do FGTS por tipo de desligamento',
  descricaoSEO:'Calcule a rescisão do contrato CLT em 2026: saldo de salário, aviso prévio, 13º e férias proporcionais com o terço, INSS e imposto de renda, multa de 40% ou 20% do FGTS. Dispensa sem justa causa, pedido de demissão, acordo ou justa causa. Grátis, sem cadastro.',
  introducao:'Quando o contrato acaba, a empresa tem até 10 dias para pagar o acerto (CLT, art. 477, § 6º), e o que entra nele depende de como o contrato acabou. Na dispensa sem justa causa vem tudo: saldo de salário, aviso prévio (30 dias mais 3 por ano na empresa, até 90), 13º e férias proporcionais com o terço, as férias vencidas e a multa de 40% do FGTS. No pedido de demissão não há aviso indenizado nem multa, e quem sai sem cumprir o aviso pode ter um salário descontado. No acordo entre empregado e empresa (art. 484-A da CLT) o aviso indenizado e a multa caem pela metade: 20%. Na justa causa sobram só o saldo de salário e as férias vencidas. A calculadora monta o acerto verba a verba, desconta o INSS e o imposto de renda de 2026 onde eles incidem (saldo de salário e 13º; aviso e férias indenizados são isentos) e mostra a multa do FGTS separada, porque ela sai pela conta do FGTS, não pelo acerto.',
  passos:['Informe o salário bruto mensal, a data de admissão e o último dia trabalhado. Se o aviso foi trabalhado, o desligamento é o último dia do aviso. A calculadora conta os anos completos na empresa para o aviso prévio e o período aquisitivo das férias a partir dessas datas.','Escolha o tipo de desligamento e, com ele, a situação do aviso prévio: indenizado (pago no acerto, com o contrato projetado para o 13º e as férias), trabalhado, dispensado pela empresa ou não cumprido. Cada tipo liga e desliga verbas e a multa do FGTS.','Diga quantos períodos de férias completos você ainda não tirou (as vencidas) e quantos dependentes declara no imposto de renda. Se tiver o extrato do FGTS, informe o saldo: a multa é calculada sobre ele mais os depósitos do acerto. Em branco, a calculadora estima 8% do salário por mês de contrato, sem os rendimentos da conta.'],
  exemplos:[
   {titulo:'Dispensa sem justa causa: R$ 3.000, admitido em 10/03/2024 e desligado em 29/10/2026, aviso indenizado',conta:'Dois anos completos: aviso prévio de 36 dias, R$ 3.600,00, e o contrato se projeta até 04/12/2026. Saldo de salário: 29 dias, R$ 2.900,00. 13º proporcional: 11 avos de 2026 (dezembro fica com 4 dias e não conta), R$ 2.750,00. Férias proporcionais: 9 avos do período que começou em 10/03/2026, R$ 2.250,00, mais R$ 750,00 do terço. Verbas: R$ 12.250,00. Descontos: INSS de R$ 236,69 sobre o saldo e de R$ 223,19 sobre o 13º; imposto de renda zero nos dois. Acerto: R$ 11.790,12. Multa do FGTS: 40% sobre R$ 7.440,00 estimados na conta mais R$ 740,00 dos depósitos do acerto, R$ 3.272,00. Total: R$ 15.062,12.',leitura:'O aviso indenizado faz mais do que pagar 36 dias: ele empurra o fim do contrato para dezembro e dá mais um avo de 13º e de férias. Repare que o aviso, as férias e a multa não têm desconto nenhum: o INSS e o imposto só incidem sobre o saldo de salário e o 13º, cada um calculado por si.'},
   {titulo:'Pedido de demissão: R$ 2.500, admitido em 01/08/2025 e saiu em 15/10/2026 com o aviso trabalhado',conta:'Saldo de salário: 15 dias, R$ 1.250,00. 13º proporcional: 10 avos (outubro tem 15 dias e conta), R$ 2.083,33. Férias proporcionais: 3 avos do período que começou em 01/08/2026, R$ 625,00, mais R$ 208,33 do terço. Verbas: R$ 4.166,66. INSS de R$ 93,75 sobre o saldo e de R$ 163,18 sobre o 13º; imposto de renda zero. Acerto: R$ 3.909,73. Sem aviso indenizado, sem multa e sem saque do FGTS. Se o aviso não fosse cumprido, a empresa poderia descontar um salário, R$ 2.500,00, e o acerto cairia para R$ 1.409,73.',leitura:'Quem pede demissão recebe o 13º e as férias proporcionais mesmo com menos de um ano de casa (Súmula 261 do TST), mas perde o aviso indenizado, a multa de 40%, o saque do FGTS e o seguro-desemprego. Cumprir o aviso evita o desconto de um salário, que aqui levaria quase dois terços do acerto.'},
   {titulo:'Acordo (art. 484-A): R$ 5.000 com 1 dependente, admitido em 15/01/2020 e desligado em 29/10/2026, 1 período de férias vencido, R$ 30 mil de FGTS',conta:'Seis anos completos: aviso de 48 dias, R$ 8.000,00, pago pela metade no acordo, R$ 4.000,00, com o contrato projetado até 16/12/2026. Saldo de salário: 29 dias, R$ 4.833,33. 13º: 12 avos, R$ 5.000,00. Férias vencidas: R$ 5.000,00 mais R$ 1.666,67 do terço. Férias proporcionais: 11 avos, R$ 4.583,33 mais R$ 1.527,78. Verbas: R$ 26.611,11. INSS de R$ 478,18 sobre o saldo e de R$ 501,51 sobre o 13º; imposto de renda zero nos dois (sobre o saldo, a tabela daria R$ 261,76, zerados pela redução da Lei 15.270). Acerto: R$ 25.631,42. Multa do FGTS: 20% sobre R$ 30.000,00 mais R$ 1.106,67 dos depósitos do acerto, R$ 6.221,33. Total: R$ 31.852,75.',leitura:'No acordo o empregado troca metade do aviso indenizado, metade da multa e o seguro-desemprego pelo direito de sacar 80% do FGTS. Com o saldo informado, a multa deixa de ser estimativa: R$ 6.221,33 em vez dos R$ 12.442,67 que viriam na dispensa sem justa causa.'}
  ],
  perguntas:[
   {pergunta:'O que entra na rescisão em cada tipo de desligamento?',resposta:'Saldo de salário e férias vencidas com o terço entram sempre, até na justa causa. O 13º e as férias proporcionais entram em todos os tipos menos na justa causa. O aviso prévio indenizado e a multa do FGTS só entram na dispensa sem justa causa (aviso cheio e 40%) e no acordo do art. 484-A (metade do aviso e 20%). O saque do FGTS e o seguro-desemprego, que não são verbas do acerto, valem na dispensa sem justa causa; no acordo, o saque é de 80% e não há seguro-desemprego; no pedido de demissão e na justa causa, nem um nem outro.'},
   {pergunta:'Como se conta o aviso prévio?',resposta:'São 30 dias para quem tem até um ano de casa e 3 dias a mais por ano completo na mesma empresa, até 90 dias com 20 anos ou mais (Lei 12.506/2011). Indenizado, ele é pago no acerto e o contrato se projeta por esses dias: o 13º e as férias proporcionais são contados até o fim da projeção (CLT, art. 487, § 1º). Trabalhado, o empregado cumpre 30 dias com a jornada reduzida em 2 horas ou com 7 dias de folga no fim (art. 488), e os dias a mais por ano de casa são indenizados (Nota Técnica 184/2012 do Ministério do Trabalho). No pedido de demissão, quem não cumpre o aviso pode ter um salário descontado, a menos que a empresa dispense o cumprimento.'},
   {pergunta:'Quais descontos tem a rescisão?',resposta:'INSS e imposto de renda incidem sobre o saldo de salário e, separadamente, sobre o 13º proporcional, pelas tabelas de 2026 (as mesmas do salário líquido, com a redução da Lei 15.270/2025). Não incidem sobre o aviso prévio indenizado, as férias indenizadas (vencidas e proporcionais) com o terço nem sobre a multa do FGTS. A empresa também pode descontar adiantamentos, vale-transporte do mês e, no pedido de demissão sem o aviso cumprido, um salário (CLT, art. 487, § 2º).'},
   {pergunta:'Férias vencidas e proporcionais: qual é a diferença?',resposta:'Férias vencidas são os períodos de 12 meses já completos que você ainda não tirou: cada um vale um salário mais um terço, em qualquer tipo de desligamento. Férias proporcionais são 1/12 por mês do período em curso, contado data a data a partir do aniversário da admissão; um mês com 15 dias ou mais conta inteiro (CLT, arts. 146 e 147). Elas não são devidas na justa causa. Um período vencido há mais de um ano sem gozo é pago em dobro (art. 137), e a calculadora não faz essa dobra: informe só os períodos simples e confira o TRCT.'},
   {pergunta:'Como a multa do FGTS é calculada?',resposta:'A multa é de 40% na dispensa sem justa causa e de 20% no acordo, sobre todos os depósitos do FGTS feitos durante o contrato, com os rendimentos, mais os 8% sobre as verbas do acerto que têm FGTS (saldo de salário, 13º e aviso indenizado). Ela é depositada na conta do FGTS, não paga em dinheiro no acerto, e o trabalhador saca junto com o saldo. Se você informar o saldo do extrato (aplicativo FGTS), a conta usa esse valor; em branco, a calculadora estima 8% do salário por mês de contrato, o que ignora os rendimentos e os saques já feitos.'},
   {pergunta:'Em quanto tempo a empresa tem de pagar?',resposta:'Até 10 dias corridos depois do fim do contrato (CLT, art. 477, § 6º), com aviso indenizado ou trabalhado. Se atrasar, deve ao empregado uma multa de um salário (§ 8º), além do acerto. O termo de rescisão (TRCT) discrimina cada verba e cada desconto: confira com a tabela desta página.'}
  ],
  atencao:'Simulação com os valores que você digitou; não é previsão nem recomendação. As tabelas de INSS e imposto de renda são as de 2026 (Portaria Interministerial MPS/MF nº 13/2026; Leis 15.191/2025 e 15.270/2025) e a conta vale para empregado CLT com contrato por prazo indeterminado e salário fixo. Ficam de fora: contrato de experiência e por prazo determinado, horas extras e médias, adiantamento do 13º já pago, faltas e afastamentos que tiram avos, a dobra das férias vencidas, pensão alimentícia, seguro-desemprego e o saque do FGTS. O saldo do FGTS em branco é uma estimativa simples. Cada empresa arredonda do seu jeito e algumas convenções coletivas dão mais: confira o TRCT.'},
 'ferias':{revisadoEm:'2026-10-29',
  // Rascunho do Claude em 29/10/2026 (nível 1: o texto público espera o "pode" do Tiago); os números dos exemplos saem de lib/calculos/ferias.ts e o teste confere.
  titulo:'Férias 2026: quanto cai na conta com o terço, o abono pecuniário e o adiantamento do 13º',
  descricaoSEO:'Calcule as férias CLT em 2026: férias com um terço, venda de até 10 dias (abono pecuniário), adiantamento do 13º, INSS e imposto de renda calculados em separado do salário. Veja o líquido e até quando a empresa deve pagar. Grátis, sem cadastro.',
  introducao:'Depois de 12 meses de trabalho, o empregado CLT tem direito a 30 dias de férias (menos, se faltou sem justificar), pagos até 2 dias antes de começarem (CLT, art. 145). O valor é o salário dos dias de descanso mais um terço (Constituição, art. 7º, XVII). Quem quiser pode vender até um terço dos dias para a empresa, o abono pecuniário, e pedir que metade do 13º venha junto. A calculadora monta o recibo de férias linha a linha: as férias e o terço, com o INSS e o imposto de renda de 2026 calculados em separado do salário do mês; o abono com o seu terço e o adiantamento do 13º, que não têm desconto; e o líquido que cai na conta. Se você informar o primeiro dia das férias, ela mostra a data limite do pagamento.',
  passos:['Informe o salário bruto mensal e, se tiver, a média mensal de horas extras, adicionais e comissões do período: ela entra na base das férias e do terço (CLT, art. 142), mas não no adiantamento do 13º.','Diga quantas faltas sem justificativa teve nos 12 meses do período aquisitivo: elas definem quantos dias de férias você tem (30, 24, 18 ou 12). Depois escolha quantos dias quer vender (até um terço) e quantos vai tirar agora, se for dividir as férias em períodos.','Marque se pediu a primeira parcela do 13º junto com as férias, informe os dependentes do imposto de renda e, se quiser saber a data limite do pagamento, o primeiro dia das férias.'],
  exemplos:[
   {titulo:'R$ 3.000, 30 dias de férias, sem vender dias nem adiantar o 13º',conta:'Férias: 30 dias sobre R$ 3.000,00, R$ 3.000,00. Terço constitucional: R$ 1.000,00. Base dos descontos: R$ 4.000,00. INSS por faixa: R$ 368,60. Imposto de renda: a tabela daria R$ 114,76, zerados pela redução da Lei 15.270 para quem recebe até R$ 5.000. Cai na conta: R$ 3.631,40.',leitura:'Um mês inteiro de férias rende mais do que um mês de salário: o terço entra sem aumentar o INSS na mesma proporção, porque a tabela é por faixa. Repare que o imposto de renda das férias é calculado em separado do salário, por isso a redução zera o imposto aqui mesmo que o salário do mês também tenha a sua.'},
   {titulo:'R$ 3.000, vende 10 dias e tira 20, com o adiantamento do 13º',conta:'Férias: 20 dias, R$ 2.000,00, mais R$ 666,67 do terço. Abono pecuniário: 10 dias, R$ 1.000,00, mais R$ 333,33 do terço sobre o abono. Adiantamento do 13º: metade do salário, R$ 1.500,00. Verbas: R$ 5.500,00. INSS só sobre as férias e o terço (R$ 2.666,67): R$ 215,69; imposto de renda zero. Cai na conta: R$ 5.284,31.',leitura:'Vender 10 dias troca descanso por dinheiro sem desconto: o abono e o seu terço são isentos de INSS e de imposto de renda. O adiantamento do 13º também vem limpo, mas não é dinheiro novo: em dezembro a segunda parcela já vem com os descontos do 13º inteiro e menos essa metade.'},
   {titulo:'R$ 8.000, 30 dias de férias',conta:'Férias: R$ 8.000,00, mais R$ 2.666,67 do terço; base dos descontos de R$ 10.666,67. INSS no teto: R$ 988,09. Imposto de renda pela tabela de 27,5%: R$ 1.752,88, sem redução (a redução da Lei 15.270 acaba em R$ 7.350 de rendimento). Cai na conta: R$ 7.925,70.',leitura:'Acima do teto do INSS o desconto previdenciário para de crescer, e o imposto de renda passa a ser o desconto maior: as férias com o terço somam R$ 10.666,67 e caem para R$ 7.925,70 líquidos. O terço, apesar do nome de indenização, entra na base dos dois descontos quando as férias são gozadas (STF, Tema 985).'}
  ],
  perguntas:[
   {pergunta:'Quantos dias de férias eu tenho?',resposta:'Trinta dias corridos por período aquisitivo de 12 meses, se você teve até 5 faltas sem justificativa; de 6 a 14 faltas, 24 dias; de 15 a 23, 18 dias; de 24 a 32, 12 dias; acima disso, o direito às férias daquele período se perde (CLT, art. 130). Faltas justificadas (atestado, casamento, nascimento de filho, doação de sangue, as do art. 473) não contam. O empregador escolhe a época dentro dos 12 meses seguintes ao período aquisitivo e avisa com 30 dias de antecedência (arts. 134 e 135).'},
   {pergunta:'O que é o terço constitucional?',resposta:'É um terço a mais sobre o valor das férias, garantido pela Constituição (art. 7º, XVII): 30 dias de férias de quem ganha R$ 3.000 valem R$ 3.000 mais R$ 1.000. O terço também é pago sobre o abono pecuniário. Quando as férias são gozadas, o terço entra na base do INSS (STF, Tema 985) e do imposto de renda; só as férias indenizadas na rescisão, com o terço, são isentas.'},
   {pergunta:'Como funciona o abono pecuniário (vender férias)?',resposta:'Você pode converter até um terço dos dias de férias em dinheiro (CLT, art. 143): 10 dias, se tem direito a 30. O pedido é feito até 15 dias antes de o período aquisitivo terminar, e a empresa não pode recusar nem impor. Os dias vendidos são pagos como salário mais o terço, e esse valor é isento de INSS (Lei 8.212/1991, art. 28, § 9º) e de imposto de renda (Lei 7.713/1988, art. 6º). Em troca, você descansa menos: 20 dias em vez de 30.'},
   {pergunta:'Posso receber o 13º junto com as férias?',resposta:'Sim. Quem pede em janeiro recebe a primeira parcela do 13º junto com as férias (Lei 4.749/1965, art. 2º): metade do salário do mês anterior, sem desconto nessa hora. Não é dinheiro a mais: em dezembro a empresa paga a segunda parcela com o 13º inteiro recalculado, desconta o INSS e o imposto de renda do 13º e abate o que adiantou. A conta aqui mostra o adiantamento com metade do salário fixo, sem as médias.'},
   {pergunta:'Quais descontos tem o pagamento das férias?',resposta:'INSS e imposto de renda, pelas tabelas de 2026 (as mesmas do salário líquido, com a redução da Lei 15.270/2025), calculados sobre as férias mais o terço, em separado do salário do mês (IN RFB 1.500/2014, art. 12). O abono pecuniário com o seu terço e o adiantamento do 13º não têm desconto. Também não entram aqui vale-transporte, plano de saúde e pensão alimentícia, que seguem no salário. Como o imposto das férias é apurado à parte, pode acontecer de ele ficar em zero mesmo quando o salário do mês tem imposto.'},
   {pergunta:'Quando a empresa tem de pagar, e posso dividir as férias?',resposta:'O pagamento, com o terço e o abono, é feito até 2 dias antes do início das férias (CLT, art. 145); se a empresa paga depois ou concede as férias fora do prazo, deve o valor em dobro (art. 137 e Súmula 450 do TST). Desde a reforma de 2017, com a concordância do empregado, as férias podem ser divididas em até três períodos: um com 14 dias ou mais e os outros com pelo menos 5 (art. 134, § 1º). A calculadora mostra o período que você vai tirar agora; o resto fica para outra data, com o mesmo cálculo por dia.'}
  ],
  atencao:'Simulação com os valores que você digitou; não é previsão nem recomendação. As tabelas de INSS e imposto de renda são as de 2026 (Portaria Interministerial MPS/MF nº 13/2026; Leis 15.191/2025 e 15.270/2025) e a conta vale para empregado CLT em férias gozadas. A redução do imposto da Lei 15.270 é aplicada como no salário; algumas empresas a tratam de outro jeito nas férias. Ficam de fora: férias proporcionais e vencidas pagas na rescisão (use a calculadora de rescisão), férias coletivas, a dobra por atraso, o salário dos dias trabalhados no mês das férias, pensão alimentícia, empregado doméstico e aprendiz. Cada empresa arredonda do seu jeito e algumas convenções coletivas dão mais: confira o recibo de férias.'},
 'correcao-ipca':{revisadoEm:'2026-10-26',titulo:'Correção pelo IPCA: atualize valores',descricaoSEO:'Atualize um valor pelo IPCA com índices do IBGE. Veja a inflação acumulada e o gráfico do período escolhido. Grátis, sem cadastro.',introducao:'Corrigir um valor pelo IPCA mostra como ele acompanha a variação do índice de preços ao consumidor. Isso ajuda a comparar valores de épocas diferentes, sem transformar a inflação em promessa de rendimento.',passos:['Informe o valor original e escolha apenas meses já disponíveis na série.','Selecione o primeiro e o último mês cujas variações devem entrar na conta. Ambos são incluídos.','Leia a correção acumulada e explore o caminho mês a mês no gráfico e na tabela.'],exemplos:[
   {titulo:'R$ 1.000 corrigidos pelo IPCA de janeiro de 2024',conta:'Com IPCA de 0,42% no mês: R$ 1.000 × 1,0042 = R$ 1.004,20.',leitura:'Informe R$ 1.000 e selecione janeiro de 2024 nos dois campos de mês. Como o início e o fim são incluídos, o índice de janeiro entra uma única vez. A atualização é de R$ 4,20.'},
   {titulo:'Correção de R$ 1.000 em janeiro e fevereiro de 2024',conta:'R$ 1.000 × 1,0042 × 1,0083 = R$ 1.012,53, arredondado aos centavos.',leitura:'Informe R$ 1.000, escolha janeiro de 2024 no início e fevereiro de 2024 no fim. Entram os índices de 0,42% e 0,83%. O índice de fevereiro incide sobre o valor já corrigido em janeiro; os fatores mensais são multiplicados.'},
   {titulo:'Um mês de deflação: agosto de 2024',conta:'Com IPCA de −0,02% no mês: R$ 1.000 × 0,9998 = R$ 999,80.',leitura:'Informe R$ 1.000 e selecione agosto de 2024 nos dois campos de mês. O valor corrigido cai R$ 0,20, porque índices negativos também entram no cálculo.'}
  ],atencao:'A ferramenta inclui os meses inicial e final, não calcula dias proporcionais e não projeta inflação futura. Contratos podem prever outro índice, período ou regra de reajuste. Confira essas condições antes de aplicar a conta.'},
 'conversor-de-moedas':{revisadoEm:'2026-10-24',titulo:'Conversor de real, dólar e euro com cotação de referência',introducao:'Converter uma moeda é multiplicar ou dividir pela relação entre os valores. Aqui a PTAX de venda serve como referência pública, sempre acompanhada da data. Ela não é uma oferta de compra ou venda.',passos:['Informe o valor, a moeda de origem e a moeda de destino.','Confira a data da cotação e a taxa mostrada na explicação.','Ao contratar câmbio, compare também a cotação efetiva, os impostos e as tarifas da operação.'],exemplos:[{titulo:'De dólar para real — cotação hipotética',conta:'US$ 100 × R$ 5,00 por dólar = R$ 500.',leitura:'Com dólar fictício de R$ 5,00, cem dólares equivalem a R$ 500 antes de qualquer custo. A cotação efetiva da calculadora aparece com sua data.'},{titulo:'Entre dólar e euro — cotações hipotéticas',conta:'US$ 100 × R$ 5,00 ÷ R$ 6,00 por euro = € 83,33.',leitura:'A conversão usa o real como moeda intermediária. As duas referências precisam ser da mesma data; misturar dias diferentes poderia distorcer a relação.'}],atencao:'O valor não inclui IOF, spread, tarifas ou preços de cartão e dinheiro em espécie. A PTAX é uma referência diária, não uma cotação em tempo real. Em fins de semana e feriados, observe a data do último dado disponível.'}
};
